mapper.select:
SELECT
,orderreceiving.task_id as orderreceivingTaskId ,orderreceiving.errands_id as orderreceivingErrandsId ,orderreceiving.orderreceiving_status_types as orderreceivingStatusTypes -- add , task.task_name as taskName ,task.yonghu_id as taskYonghuId ,task.task_uuid_number as taskUuidNumber , yonghu.yonghu_name as yonghuName , yonghu.yonghu_phone as yonghuPhone , errands.errands_name as errandsName
FROM complaint a left JOIN orderreceiving orderreceiving ON a.orderreceiving_id = orderreceiving.id -- add LEFT JOIN task task ON orderreceiving.task_id = task.id LEFT JOIN errands errands ON orderreceiving.errands_id = errands.id LEFT JOIN yonghu yonghu ON task.yonghu_id = yonghu.id
and a.id in
#{item}
and ( a.orderreceiving_id = #{params.orderreceivingId} )
and task.yonghu_id = #{params.yonghuId}
and orderreceiving.errands_id = #{params.errandsId}
and a.complaint_name like CONCAT('%',#{params.complaintName},'%')
and a.complaint_types = #{params.complaintTypes}
and a.complaint_text like CONCAT('%',#{params.complaintText},'%')
and a.complaint_yesno_types = #{params.complaintYesnoTypes}
and a.complaint_yesno_text like CONCAT('%',#{params.complaintYesnoText},'%')
and a.orderreceiving_id IS NOT NULL
and orderreceiving.orderreceiving_status_types = #{params.orderreceivingStatusTypes}
order by a.${params.orderBy} desc
